    // saw select itself, which read as a flash/glitch. Pause the loop\n    // while off-screen and restart it fresh (not from stale elapsed time)\n    // once it's back in view.\n    var isInView = false;\n    \n    function activateRole(index) {\n      currentIndex = index;\n      \n      // Update desktop selectors\n      selectors.forEach(function (card, idx) {\n        var isActive = idx === index;\n        card.classList.toggle('is-active', isActive);\n        var bar = card.querySelector('.fd-roles-selector-card__progress-bar');\n        if (bar) bar.style.transform = 'scaleX(0)';\n      });\n      \n      // Update desktop display panel\n      displayContents.forEach(function (panel, idx) {\n        panel.classList.toggle('is-active', idx === index);\n      });\n      \n      // Update mobile accordions\n      accordions.forEach(function (acc, idx) {\n        var isActive = idx === index;\n        acc.classList.toggle('is-active', isActive);\n        var trigger = acc.querySelector('.fd-roles-accordion-trigger');\n        if (trigger) {\n          trigger.setAttribute('aria-expanded', isActive ? 'true' : 'false');\n        }\n      });\n      \n      // Restart progress bar animation if auto-rotation is active\n      if (!isUserInteracted) {\n        startTime = Date.now();\n        animateProgressBar();\n      }\n    }\n    \n    function animateProgressBar() {\n      if (isUserInteracted || !isInView) return;\n      cancelAnimationFrame(progressAnimFrame);\n\n      var activeCard = showcase.querySelector('.fd-roles-selector-card.is-active');\n      if (!activeCard) return;\n      var bar = activeCard.querySelector('.fd-roles-selector-card__progress-bar');\n\n      function step() {\n        if (isUserInteracted || !isInView) return;\n        var now = Date.now();\n        var progress = (now - startTime) / duration;\n        if (progress >= 1) {\n          if (bar) bar.style.transform = 'scaleX(1)';\n          // Move to next role\n          var nextIndex 